#!/usr/bin/env bash
set -euo pipefail
cd "${1:-$(pwd)}"
test -f package.json || { echo "Voer dit uit in /workspaces/BlueLog"; exit 1; }

echo '' | base64 -d > 'app/api/dives/[id]/route.ts'
echo '' | base64 -d > app/dives/page.tsx

npm run build

echo
echo "KLAAR."
echo "Push daarna met:"
echo "git add app/dives/page.tsx 'app/api/dives/[id]/route.ts'"
echo "git commit -m 'Add backup export and photo cleanup'"
echo "git push"
